use serde::Deserialize;
use serde_json::{json,Value};
use uuid::Uuid;
use crate::{connectors,error::ApiError,models::{Diagnostics,User},AppState};

#[derive(Deserialize)]#[serde(rename_all="camelCase")]
pub struct CompanyInput{pub id:String,pub company_name:String,#[serde(default)]pub countries:Vec<String>,pub ats_provider:String,pub board_identifier:String,#[serde(default)]pub careers_url:String,pub identifier_origin:String}

pub async fn overview(state:&AppState)->Result<Value,ApiError>{
 let users:i64=sqlx::query_scalar("SELECT count(*) FROM users").fetch_one(&state.db).await?;let admins:i64=sqlx::query_scalar("SELECT count(*) FROM users WHERE role='admin'").fetch_one(&state.db).await?;let profiles:i64=sqlx::query_scalar("SELECT count(*) FROM profiles").fetch_one(&state.db).await?;let sources:i64=sqlx::query_scalar("SELECT count(*) FROM sources WHERE enabled=true").fetch_one(&state.db).await?;let jobs:i64=sqlx::query_scalar("SELECT count(*) FROM jobs WHERE active=true").fetch_one(&state.db).await?;let companies:i64=sqlx::query_scalar("SELECT count(*) FROM company_directory").fetch_one(&state.db).await?;
 Ok(json!({"users":users,"admins":admins,"profiles":profiles,"enabledSources":sources,"activeJobs":jobs,"companies":companies,"database":"PostgreSQL"}))
}

pub async fn diagnostics(state:&AppState)->Result<Diagnostics,ApiError>{
 let active_jobs=sqlx::query_scalar("SELECT count(*) FROM jobs WHERE active=true").fetch_one(&state.db).await?;let inactive_jobs=sqlx::query_scalar("SELECT count(*) FROM jobs WHERE active=false").fetch_one(&state.db).await?;let profiles=sqlx::query_scalar("SELECT count(*) FROM profiles").fetch_one(&state.db).await?;let enabled_sources=sqlx::query_scalar("SELECT count(*) FROM sources s WHERE s.enabled=true AND NOT EXISTS(SELECT 1 FROM company_directory d WHERE d.enabled=false AND lower(btrim(d.company_name))=lower(btrim(s.company)))").fetch_one(&state.db).await?;let search_runs=sqlx::query_scalar("SELECT count(*) FROM search_runs").fetch_one(&state.db).await?;let source_errors=sqlx::query_scalar("SELECT count(*) FROM sources WHERE last_error IS NOT NULL").fetch_one(&state.db).await?;let due_follow_ups=sqlx::query_scalar("SELECT count(*) FROM trackers WHERE follow_up_at IS NOT NULL AND follow_up_at<>'' AND follow_up_at::timestamptz<=now()").fetch_one(&state.db).await?;let database_size_bytes=sqlx::query_scalar("SELECT pg_database_size(current_database())").fetch_one(&state.db).await?;
 Ok(Diagnostics{database_path:"PostgreSQL (site-wide)".into(),database_size_bytes,active_jobs,inactive_jobs,profiles,enabled_sources,search_runs,source_errors,due_follow_ups})
}

pub async fn retention(state:&AppState,days:i64)->Result<i64,ApiError>{if !(7..=3650).contains(&days){return Err(ApiError::BadRequest("Retention must be between 7 and 3650 days.".into()));}let mut tx=state.db.begin().await?;let jobs=sqlx::query("DELETE FROM jobs WHERE active=false AND last_seen_at<now()-make_interval(days=>$1::int)").bind(days as i32).execute(&mut *tx).await?.rows_affected();let runs=sqlx::query("DELETE FROM search_runs WHERE started_at::timestamptz<now()-make_interval(days=>$1::int)").bind(days as i32).execute(&mut *tx).await?.rows_affected();tx.commit().await?;Ok((jobs+runs)as i64)}

pub async fn users(state:&AppState)->Result<Vec<User>,ApiError>{Ok(sqlx::query_as("SELECT id,email,display_name,role FROM users ORDER BY email").fetch_all(&state.db).await?)}

pub async fn set_role(state:&AppState,actor:Uuid,user:Uuid,role:&str)->Result<User,ApiError>{
 if role!="user"&&role!="admin"{return Err(ApiError::BadRequest("Role must be user or admin.".into()));}
 if actor==user&&role!="admin"{return Err(ApiError::BadRequest("Administrators cannot remove their own admin role.".into()));}
 Ok(sqlx::query_as("UPDATE users SET role=$2 WHERE id=$1 RETURNING id,email,display_name,role").bind(user).bind(role).fetch_optional(&state.db).await?.ok_or(ApiError::NotFound)?)
}

pub async fn set_all_schedules(state:&AppState,schedule:&str)->Result<u64,ApiError>{if !["Manual","Daily","Weekdays","Weekly"].contains(&schedule){return Err(ApiError::BadRequest("Unsupported schedule.".into()));}let mut tx=state.db.begin().await?;sqlx::query("INSERT INTO site_settings(key,value) VALUES('global_schedule',$1) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=now()").bind(schedule).execute(&mut *tx).await?;let changed=sqlx::query("UPDATE profiles SET schedule=$1,next_run_at=NULL,updated_at=now()").bind(schedule).execute(&mut *tx).await?.rows_affected();tx.commit().await?;Ok(changed)}

pub async fn save_company(state:&AppState,input:CompanyInput)->Result<(),ApiError>{
 let provider=input.ats_provider.trim();if !["Greenhouse","Lever","Ashby","SmartRecruiters","Amazon","Workday","Microsoft","Google","CareerPage","Adzuna"].contains(&provider){return Err(ApiError::BadRequest("Unsupported company connector.".into()));}
 let requested_id=input.id.trim().to_lowercase().chars().map(|c|if c.is_ascii_alphanumeric(){c}else{'-'}).collect::<String>();if requested_id.trim_matches('-').is_empty()||input.company_name.trim().is_empty()||input.board_identifier.trim().is_empty(){return Err(ApiError::BadRequest("Company name and board identifier are required.".into()));}let existing_id:Option<String>=sqlx::query_scalar("SELECT id FROM company_directory WHERE lower(btrim(company_name))=lower(btrim($1)) LIMIT 1").bind(input.company_name.trim()).fetch_optional(&state.db).await?;let id=existing_id.unwrap_or_else(||requested_id.trim_matches('-').to_string());
 let careers_url=if !input.careers_url.trim().is_empty(){input.careers_url.trim().to_string()}else{match provider{"Greenhouse"=>format!("https://boards.greenhouse.io/{}",input.board_identifier),"Lever"=>format!("https://jobs.lever.co/{}",input.board_identifier),"Ashby"=>format!("https://jobs.ashbyhq.com/{}",input.board_identifier),"SmartRecruiters"=>format!("https://jobs.smartrecruiters.com/{}",input.board_identifier),"Amazon"=>"https://www.amazon.jobs/en/search".into(),"Microsoft"=>"https://apply.careers.microsoft.com/careers?domain=microsoft.com".into(),"Google"=>"https://www.google.com/about/careers/applications/jobs/results".into(),"Adzuna"=>"https://www.adzuna.com/search".into(),"Workday"|"CareerPage"=>return Err(ApiError::BadRequest("Workday and career-page companies require a careers URL.".into())),_=>unreachable!()}};
 let origin=if input.identifier_origin=="Automatic"{"Automatic"}else{"Manual"};sqlx::query("INSERT INTO company_directory(id,company_name,countries,ats_provider,connector_class,board_identifier,careers_url,identifier_origin) VALUES($1,$2,$3,$4,$5,$6,$7,$8) ON CONFLICT(id) DO UPDATE SET company_name=excluded.company_name,countries=excluded.countries,ats_provider=excluded.ats_provider,connector_class=excluded.connector_class,board_identifier=excluded.board_identifier,careers_url=excluded.careers_url,identifier_origin=excluded.identifier_origin,verification_status='Pending',verification_error=NULL,next_verification_at=now(),updated_at=now()")
 .bind(id).bind(input.company_name.trim()).bind(json!(input.countries)).bind(provider).bind(connectors::connector_class(provider)).bind(input.board_identifier.trim()).bind(careers_url).bind(origin).execute(&state.db).await?;Ok(())
}

pub async fn delete_company(state:&AppState,id:&str)->Result<u64,ApiError>{let company:Option<String>=sqlx::query_scalar("SELECT company_name FROM company_directory WHERE id=$1").bind(id).fetch_optional(&state.db).await?;let Some(company)=company else{return Ok(0)};let mut tx=state.db.begin().await?;sqlx::query("UPDATE jobs SET active=false WHERE lower(btrim(company))=lower(btrim($1)) OR source_id IN(SELECT s.id FROM sources s WHERE s.user_id=jobs.user_id AND lower(btrim(s.company))=lower(btrim($1)))").bind(&company).execute(&mut *tx).await?;sqlx::query("DELETE FROM sources WHERE lower(btrim(company))=lower(btrim($1))").bind(&company).execute(&mut *tx).await?;sqlx::query("DELETE FROM company_directory_preferences WHERE company_key=lower(btrim($1))").bind(&company).execute(&mut *tx).await?;let result=sqlx::query("DELETE FROM company_directory WHERE id=$1").bind(id).execute(&mut *tx).await?;tx.commit().await?;Ok(result.rows_affected())}
